# owner: platform
"""Contact sheet for substitute teachers."""

from rosterkit.errors import ProjectError

def _check(students):
    if not students:
        raise ProjectError("no students")
    for item in students:
        if not item.email:
            raise ProjectError(
                f"no email: {item.display_name}"
            )

def _name(item):
    return item.display_name

def _cells(students):
    return [
        (item.display_name, item.section, item.email)
        for item in sorted(students, key=_name)
    ]

def _widths(cells):
    return [
        max(len(cell) for cell in column)
        for column in zip(*cells)
    ]

def _join(row, widths):
    pairs = zip(row, widths)
    return "  ".join(
        cell.ljust(wide) for cell, wide in pairs
    ).rstrip()

# ---
def contact_rows(students):
    _check(students)
    cells = _cells(students)
    widths = _widths(cells)
    return [_join(row, widths) for row in cells]

